import sys

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT / "tools" / "mindustry_godot_transpiler"))

from mindustry_port import source_symbols, source_ssot


class SourceSymbolRegistryTests(unittest.TestCase):
    def test_source_ssot_catalog_defines_canonical_json_modules(self):
        import importlib

        source_ssot = importlib.import_module("mindustry_port.source_ssot")

        self.assertEqual(source_ssot.module_names(), ["registry", "audit_report", "slice_ledger", "api_contracts", "state_schema", "playable_content", "asset_manifest", "source_manifest", "ast_manifest", "content_registry", "emitted_classes", "port_report"])
        self.assertEqual(source_ssot.extension_manifest_relative_path().as_posix(), "src/generated/source_ssot_modules.json")
        self.assertEqual(source_ssot.relative_path("registry").as_posix(), "src/generated/source_symbol_registry.json")
        self.assertEqual(source_ssot.relative_path("audit_report").as_posix(), "src/generated/source_symbol_audit_report.json")
        self.assertEqual(source_ssot.relative_path("slice_ledger").as_posix(), "src/generated/source_slice_ledger.json")
        self.assertEqual(source_ssot.relative_path("api_contracts").as_posix(), "src/generated/source_api_contracts.json")
        self.assertEqual(source_ssot.relative_path("state_schema").as_posix(), "src/generated/source_state_schema.json")
        self.assertEqual(source_ssot.relative_path("playable_content").as_posix(), "src/generated/playable_content.json")
        self.assertEqual(source_ssot.relative_path("asset_manifest").as_posix(), "src/generated/asset_manifest.json")
        self.assertEqual(source_ssot.relative_path("source_manifest").as_posix(), "src/generated/source_manifest.json")
        self.assertEqual(source_ssot.relative_path("ast_manifest").as_posix(), "src/generated/ast_manifest.json")
        self.assertEqual(source_ssot.relative_path("content_registry").as_posix(), "src/generated/content_registry.json")
        self.assertEqual(source_ssot.relative_path("emitted_classes").as_posix(), "src/generated/emitted_classes.json")
        self.assertEqual(source_ssot.relative_path("port_report").as_posix(), "src/generated/port_report.json")
        self.assertEqual(source_ssot.root_key("registry"), "symbols")
        self.assertEqual(source_ssot.root_key("slice_ledger"), "slices")
        self.assertEqual(source_ssot.root_key("playable_content"), "")
        self.assertEqual(source_ssot.root_key("asset_manifest"), "")
        self.assertEqual(source_ssot.root_key("source_manifest"), "")
        self.assertEqual(source_ssot.root_key("ast_manifest"), "")
        self.assertEqual(source_ssot.root_key("content_registry"), "")
        self.assertEqual(source_ssot.root_key("emitted_classes"), "")
        self.assertEqual(source_ssot.root_key("port_report"), "")
        self.assertEqual(source_ssot.runtime_label("state_schema"), "schemaName")
        self.assertEqual(source_ssot.runtime_label("playable_content"), "")
        self.assertEqual(source_ssot.runtime_label("asset_manifest"), "")
        self.assertEqual(source_ssot.runtime_label("source_manifest"), "")
        self.assertEqual(source_ssot.runtime_label("ast_manifest"), "")
        self.assertEqual(source_ssot.runtime_label("content_registry"), "")
        self.assertEqual(source_ssot.runtime_label("emitted_classes"), "")
        self.assertEqual(source_ssot.runtime_label("port_report"), "")
        self.assertEqual(source_ssot.load_json(ROOT / "godot-mindustry", "registry")["version"], 1)
        self.assertEqual(source_ssot.load_json(ROOT / "godot-mindustry", "playable_content")["tile_size"], 32)
        self.assertEqual(source_ssot.load_json(ROOT / "godot-mindustry", "asset_manifest")["asset_count"], 2970)
        self.assertEqual(source_ssot.load_json(ROOT / "godot-mindustry", "source_manifest")["java_file_count"], 801)
        self.assertEqual(source_ssot.load_json(ROOT / "godot-mindustry", "ast_manifest")["parsed_file_count"], 8)
        self.assertEqual(source_ssot.load_json(ROOT / "godot-mindustry", "content_registry")["counts"]["blocks"], 417)
        self.assertEqual(source_ssot.load_json(ROOT / "godot-mindustry", "emitted_classes")["emitted_file_count"], 801)
        self.assertEqual(len(source_ssot.load_json(ROOT / "godot-mindustry", "port_report")["unsupported_features"]), 6986)
        self.assertIn("consumer_slices", source_ssot.registered_module_names(ROOT / "godot-mindustry"))

    def test_source_ssot_catalog_loads_and_writes_modules_by_name(self):
        import importlib

        source_ssot = importlib.import_module("mindustry_port.source_ssot")

        with tempfile.TemporaryDirectory() as tmp:
            godot_root = Path(tmp)
            for module_name in source_ssot.module_names():
                path = godot_root / source_ssot.relative_path(module_name)
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text('{"version": 1, "module": "' + module_name + '"}\n', encoding="utf-8")

            loaded = source_ssot.load_all_json(godot_root)
            self.assertEqual(sorted(loaded.keys()), sorted(source_ssot.module_names()))
            self.assertEqual(loaded["registry"]["module"], "registry")

            source_ssot.write_json(godot_root, "state_schema", {"version": 2, "module": "state_schema"})
            self.assertEqual(source_ssot.load_json(godot_root, "state_schema")["version"], 2)

    def test_source_ssot_writer_preserves_canonical_insertion_order(self):
        import importlib

        source_ssot = importlib.import_module("mindustry_port.source_ssot")

        with tempfile.TemporaryDirectory() as tmp:
            godot_root = Path(tmp)
            source_ssot.write_json(godot_root, "state_schema", {
                "version": 1,
                "schemas": {},
                "policy": {"newSchemaRequiresSource": True},
            })

            text = (godot_root / source_ssot.relative_path("state_schema")).read_text(encoding="utf-8")
            self.assertLess(text.index('"version"'), text.index('"schemas"'))
            self.assertLess(text.index('"schemas"'), text.index('"policy"'))

    def test_source_ssot_catalog_loads_extension_modules_from_manifest(self):
        import importlib

        source_ssot = importlib.import_module("mindustry_port.source_ssot")

        with tempfile.TemporaryDirectory() as tmp:
            godot_root = Path(tmp)
            for module_name in source_ssot.module_names():
                payload = {"version": 1}
                root_key = source_ssot.root_key(module_name)
                if root_key:
                    payload[root_key] = {}
                source_ssot.write_json(godot_root, module_name, payload)
            manifest_path = godot_root / source_ssot.extension_manifest_relative_path()
            manifest_path.parent.mkdir(parents=True, exist_ok=True)
            manifest_path.write_text(
                '{"version": 1, "modules": {"consumer_slices": {"path": "src/generated/source_modules/consumer_slices.json", "root_key": "slices", "label": "sliceId"}}}\n',
                encoding="utf-8",
            )
            extension_path = godot_root / "src/generated/source_modules/consumer_slices.json"
            extension_path.parent.mkdir(parents=True, exist_ok=True)
            extension_path.write_text('{"version": 1, "slices": {"NTEST": {"status": "reserved"}}}\n', encoding="utf-8")

            self.assertEqual(source_ssot.registered_module_names(godot_root)[-2:], ["module_manifest", "consumer_slices"])
            self.assertEqual(source_ssot.registered_relative_path(godot_root, "consumer_slices").as_posix(), "src/generated/source_modules/consumer_slices.json")
            self.assertEqual(source_ssot.load_registered_json(godot_root, "consumer_slices")["slices"]["NTEST"]["status"], "reserved")
            report = source_ssot.validate_json_modules(godot_root)
            self.assertEqual(report["errors"], [])

