    def test_source_ssot_bullet_json_shards_declare_canonical_mirror_contracts(self):
        import importlib

        source_ssot = importlib.import_module("mindustry_port.source_ssot")

        manifest = source_ssot.load_extension_manifest(ROOT / "godot-mindustry")
        bullet_slices_entry = manifest["modules"]["bullet_slices"]
        bullet_contracts_entry = manifest["modules"]["bullet_api_contracts"]
        bullet_schema_entry = manifest["modules"]["bullet_state_schema"]
        bullet_symbols_entry = manifest["modules"]["bullet_symbols"]

        self.assertEqual(bullet_slices_entry["canonical_module"], "slice_ledger")
        self.assertEqual(bullet_slices_entry["canonical_reference_key"], "canonical_ledger")
        self.assertEqual(bullet_slices_entry["canonical_reference_prefix"], "source_slice_ledger.")
        self.assertIn("java_method", bullet_slices_entry["mirror_fields"])

        self.assertEqual(bullet_contracts_entry["canonical_module"], "api_contracts")
        self.assertEqual(bullet_contracts_entry["canonical_reference_key"], "canonical_contract")
        self.assertEqual(bullet_contracts_entry["canonical_reference_prefix"], "source_api_contracts.")
        self.assertIn("return_keys", bullet_contracts_entry["mirror_fields"])

        self.assertEqual(bullet_schema_entry["canonical_module"], "state_schema")
        self.assertEqual(bullet_schema_entry["canonical_reference_key"], "canonical_schema")
        self.assertEqual(bullet_schema_entry["canonical_reference_prefix"], "source_state_schema.")
        self.assertEqual(bullet_schema_entry["root_key"], "schemas")

        self.assertEqual(bullet_symbols_entry["canonical_module"], "registry")
        self.assertEqual(bullet_symbols_entry["canonical_reference_key"], "canonical_symbol")
        self.assertEqual(bullet_symbols_entry["canonical_reference_prefix"], "source_symbol_registry.")
        self.assertEqual(bullet_symbols_entry["root_key"], "symbols")

        canonical_slices = source_ssot.load_registered_json(ROOT / "godot-mindustry", "slice_ledger")["slices"]
        bullet_slices = source_ssot.load_registered_json(ROOT / "godot-mindustry", "bullet_slices")["slices"]
        expected_slice_ids = {
            slice_id
            for slice_id, slice_entry in canonical_slices.items()
            if "/entities/bullet/" in slice_entry["java_source"]
        }

        self.assertEqual(set(bullet_slices), expected_slice_ids)
        for slice_id in sorted(expected_slice_ids):
            with self.subTest(slice_id=slice_id):
                self.assertEqual(bullet_slices[slice_id]["canonical_ledger"], f"source_slice_ledger.{slice_id}")
                for field in bullet_slices_entry["mirror_fields"]:
                    self.assertEqual(bullet_slices[slice_id][field], canonical_slices[slice_id][field])

        bullet_contracts = source_ssot.load_registered_json(ROOT / "godot-mindustry", "bullet_api_contracts")["contracts"]
        canonical_contracts = source_ssot.load_registered_json(ROOT / "godot-mindustry", "api_contracts")["contracts"]
        expected_contract_owners = {entry["godot_owner"] for entry in bullet_slices.values()}
        self.assertEqual(set(bullet_contracts), expected_contract_owners)
        for owner in sorted(expected_contract_owners):
            with self.subTest(owner=owner):
                self.assertEqual(bullet_contracts[owner]["canonical_contract"], f"source_api_contracts.{owner}")
                for field in bullet_contracts_entry["mirror_fields"]:
                    self.assertEqual(bullet_contracts[owner][field], canonical_contracts[owner][field])

        bullet_schema = source_ssot.load_registered_json(ROOT / "godot-mindustry", "bullet_state_schema")["schemas"]
        canonical_schema = source_ssot.load_registered_json(ROOT / "godot-mindustry", "state_schema")["schemas"]
        expected_schema_names = set()
        for owner, contract in sorted(bullet_contracts.items()):
            for param in contract.get("params", []):
                schema_name = str(param["schema"]).split(".", 1)[0]
                if schema_name in canonical_schema:
                    expected_schema_names.add(schema_name)
            source_name = owner.split(".")[-1]
            if source_name.endswith("_state"):
                result_schema_name = source_name[:-len("_state")] + "_result"
                if result_schema_name in canonical_schema:
                    expected_schema_names.add(result_schema_name)
        self.assertEqual(set(bullet_schema), expected_schema_names)
        for schema_name in sorted(expected_schema_names):
            with self.subTest(schema_name=schema_name):
                self.assertEqual(bullet_schema[schema_name]["canonical_schema"], f"source_state_schema.{schema_name}")
                for field in bullet_schema_entry["mirror_fields"]:
                    self.assertEqual(bullet_schema[schema_name][field], canonical_schema[schema_name][field])

        bullet_symbols = source_ssot.load_registered_json(ROOT / "godot-mindustry", "bullet_symbols")["symbols"]
        canonical_symbols = source_ssot.load_registered_json(ROOT / "godot-mindustry", "registry")["symbols"]
        expected_symbol_names = {
            symbol_name
            for slice_entry in bullet_slices.values()
            for symbol_name in slice_entry["source_symbols"]
        }
        self.assertEqual(set(bullet_symbols), expected_symbol_names)
        for symbol_name in sorted(expected_symbol_names):
            with self.subTest(symbol_name=symbol_name):
                self.assertEqual(bullet_symbols[symbol_name]["canonical_symbol"], f"source_symbol_registry.{symbol_name}")
                for field in bullet_symbols_entry["mirror_fields"]:
                    self.assertEqual(bullet_symbols[symbol_name][field], canonical_symbols[symbol_name][field])

        report = source_ssot.validate_json_modules(ROOT / "godot-mindustry")
        bullet_reports = {entry["name"]: entry for entry in report["modules"] if entry["name"].startswith("bullet_")}
        self.assertEqual(report["errors"], [])
        self.assertEqual(bullet_reports["bullet_slices"]["canonical_mirror"]["checked"], len(bullet_slices))
        self.assertEqual(bullet_reports["bullet_api_contracts"]["canonical_mirror"]["checked"], len(bullet_contracts))
        self.assertEqual(bullet_reports["bullet_state_schema"]["canonical_mirror"]["checked"], len(bullet_schema))
        self.assertEqual(bullet_reports["bullet_symbols"]["canonical_mirror"]["checked"], len(bullet_symbols))

