        self.assertEqual(read_calls["java_expr"], "super.read(read, revision); / ammo.clear(); / totalAmmo = 0; / int amount = read.ub(); / Vars.content.item(revision < 2 ? read.ub() : read.s()) / int itemAmount = Math.min(read.s(), maxAmmo);")
        self.assertEqual(read_calls["godot_symbol"], "source_item_turret_build_read_result.read_calls")

